{
  "packet_id": "H6-T02-1",
  "claim_id": "C029",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C029",
    "value": "When the prescribed evidence does not support either good or bad classification, the revision is classified inconclusive.",
    "scope": "Residual classification outcome under the stated evidence rules.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P017 explicitly supplies inconclusive as the residual outcome of the two evidence conditions."
    }
  },
  "signal_basis": {
    "component_id": "signal_basis",
    "value": "The revision's observed fraction of exports exceeding one hour, assessed with its uncertainty under the prespecified evidence rules, supports neither the acceptable range nor the defined elevated range.",
    "scope": "Evidence used to classify an individual tested revision.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P016 identifies the measured evidence and uncertainty; P017 specifies the classification conditions and residual branch."
    }
  },
  "stated_empirical_relation": {
    "component_id": "stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim follows directly from the stated classification rule; no unresolved empirical relation is required."
    }
  },
  "rationale": "Given evidence supporting neither decisive classification, assigning inconclusive directly implements the prescribed rule. The claim stays within that procedural scope.",
  "uncertainty": "The revision's actual tail rate may remain uncertain; that uncertainty does not undermine the prescribed inconclusive classification.",
  "anomalies": []
}
